import {api,apiMode} from './api.js';
import {quote,rub,number,day,percent,esc,roundStep,matchingOffers,sumQuotes,parseNeeds,csvExport} from './domain.js';
const $=(s,base=document)=>base.querySelector(s);
const routes=['market','orders','needs','analytics'];
const labels={market:'Закупки',orders:'Мои заказы',needs:'Потребности',analytics:'Аналитика'};
const saved=(()=>{try{return JSON.parse(localStorage.getItem('optima-next-ui')||'{}')}catch{return {}}})();
let state={data:null,route:routes.includes(location.hash.slice(1))?location.hash.slice(1):'market',selected:saved.selected||'bags',qty:saved.qty||{},theme:saved.theme||'light',category:'Все',search:'',modal:null,busy:false,message:null};
const fmt=n=>number(n);
const offer=id=>state.data.offers.find(x=>x.id===id);
const selected=()=>offer(state.selected)||state.data.offers[0];
const qty=o=>state.qty[o.id]??o.defaultQuantity;
const activeOrder=id=>state.data.orders.find(x=>x.offerId===id&&x.status!=='cancelled');
const persist=()=>{try{localStorage.setItem('optima-next-ui',JSON.stringify({selected:state.selected,qty:state.qty,theme:state.theme}))}catch{}};
const status=o=>o.status==='cancelled'?'Отменена':o.status==='threshold_reached'?'Порог набран':'Сбор продолжается';
const tag=(name='plus')=>({arrow:'↗',close:'×',back:'←',plus:'+',search:'⌕'}[name]||'↗');
function sculpture(kind){
 if(kind==='bags')return `<svg viewBox="0 0 860 650" role="img" aria-label="Предметная иллюстрация курьерского пакета, раскрывающая его устройство"><defs><linearGradient id="bface" x1=".2" y1="0" x2=".8" y2="1"><stop stop-color="#fff"/><stop offset=".55" stop-color="#e8f1ef"/><stop offset="1" stop-color="#c1d5d2"/></linearGradient><linearGradient id="bflap" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#d9e9e7"/><stop offset="1" stop-color="#8aa9a9"/></linearGradient><filter id="bshadow"><feGaussianBlur stdDeviation="19"/></filter></defs>
 <ellipse cx="424" cy="555" rx="274" ry="47" fill="#173850" opacity=".2" filter="url(#bshadow)"/>
 <g transform="translate(142 72) rotate(-12 300 280)"><path d="M101 149 L536 117 Q547 119 551 133 L574 489 Q567 502 551 506 L134 535 Q120 527 114 514Z" fill="#618da0" opacity=".45" transform="translate(20 21)"/>
 <path d="M92 130 L526 99 Q538 99 539 112 L560 473 Q557 485 542 487 L125 517 Q109 514 107 497Z" fill="url(#bface)" stroke="#a5b9b5" stroke-width="2"/>
 <path d="M92 130 L526 99 L509 51 L77 79Z" fill="url(#bflap)" stroke="#97b6b6" stroke-width="2"/>
 <path d="M84 91 L515 62" stroke="#b8d0d0" stroke-width="3"/><path d="M91 111L525 82" stroke="#efffff" stroke-width="18" opacity=".82"/>
 <path d="M126 165L142 481M509 146L531 453" stroke="#88a5a4" stroke-opacity=".3" stroke-width="5"/>
 <path d="M188 231 L436 212 L446 351 L200 367Z" fill="#eff3ef" stroke="#bccbc8" stroke-width="2"/>
 <text x="216" y="253" fill="#3a5868" font-family="Arial, sans-serif" font-size="19" font-weight="700">OPTIMA / PART 01</text>
 <path d="M217 282h190" stroke="#b6c5c4" stroke-width="3"/><path d="M219 297h126" stroke="#b6c5c4" stroke-width="3"/><path d="M218 319h12m6 0h4m6 0h8m5 0h4m9 0h3m5 0h7m6 0h4m7 0h3m6 0h9m6 0h3m6 0h4m7 0h3m7 0h9m7 0h4m9 0h5" stroke="#273f4b" stroke-width="11"/>
 <path d="M114 496L546 470" stroke="#fff" stroke-opacity=".65" stroke-width="2"/></g>
 <g fill="#183b45" opacity=".8" font-family="Arial, sans-serif" font-size="17"><path d="M55 230H171M697 208H806" stroke="#37566a" stroke-width="1.5"/><circle cx="171" cy="230" r="4"/><circle cx="697" cy="208" r="4"/><text x="55" y="215" font-size="13" letter-spacing="2">КЛАПАН</text><text x="701" y="190" font-size="13" letter-spacing="2">ГЕРМЕТИЧНЫЙ</text><text x="701" y="208" font-size="12">КРАЙ</text></g></svg>`;
 if(kind==='paper')return `<svg viewBox="0 0 860 650" role="img" aria-label="Пачки офисной бумаги А4"><defs><filter id="psh"><feGaussianBlur stdDeviation="17"/></filter></defs><ellipse cx="438" cy="531" rx="260" ry="45" fill="#111e23" opacity=".19" filter="url(#psh)"/><g transform="translate(120 125) rotate(-9 310 220)"><path d="M55 99L489 44L571 139L137 191Z" fill="#f4f7f4" stroke="#9bb6ad" stroke-width="2"/><path d="M137 191L571 139L572 379L141 440Z" fill="#dfeae5"/><path d="M55 99L137 191L141 440L56 345Z" fill="#9fc2b8"/><path d="M57 319L141 412L573 353L572 379L141 440L56 345Z" fill="#f9fff9"/><path d="M182 190L496 151L499 357L181 394Z" fill="#fff"/><rect x="234" y="215" width="217" height="97" transform="rotate(-6 234 215)" fill="#1b637e"/><text x="277" y="264" fill="#fff" font-family="Arial" font-weight="700" font-size="23" transform="rotate(-6 277 264)">A4 / 80</text><path d="M191 335L468 304" stroke="#b0c8c0" stroke-width="3"/></g></svg>`;
 if(kind==='labels'||kind==='film')return `<svg viewBox="0 0 860 650" role="img" aria-label="Рулон расходных материалов"><defs><linearGradient id="rg" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#fff"/><stop offset=".55" stop-color="#d4ded7"/><stop offset="1" stop-color="#849e93"/></linearGradient><filter id="rsh"><feGaussianBlur stdDeviation="15"/></filter></defs><ellipse cx="410" cy="515" rx="240" ry="35" fill="#223e3d" opacity=".23" filter="url(#rsh)"/><g transform="translate(235 95) rotate(-9 200 240)"><path d="M95 151v246q0 108 181 107q179 0 179-107V151" fill="url(#rg)" stroke="#93a99e" stroke-width="3"/><ellipse cx="275" cy="151" rx="180" ry="90" fill="#f7faf8" stroke="#a2b7aa" stroke-width="4"/><ellipse cx="275" cy="152" rx="81" ry="42" fill="#becfc6" stroke="#82998e" stroke-width="4"/><ellipse cx="275" cy="154" rx="42" ry="22" fill="#47574e"/><path d="M95 209Q270 291 455 209M95 278Q270 353 455 278" stroke="#b8c8be" stroke-width="3"/><path d="M161 335h251" stroke="#729caf" stroke-width="23" stroke-linecap="round"/></g></svg>`;
 if(kind==='coffee')return `<svg viewBox="0 0 860 650" role="img" aria-label="Упаковка кофе в зёрнах"><defs><linearGradient id="cg" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#f7ecce"/><stop offset="1" stop-color="#bfac86"/></linearGradient><filter id="csh"><feGaussianBlur stdDeviation="16"/></filter></defs><ellipse cx="423" cy="534" rx="235" ry="36" fill="#241e18" opacity=".19" filter="url(#csh)"/><g transform="translate(260 78) rotate(7 160 240)"><path d="M45 80L284 80L327 485Q310 504 164 513Q16 506 2 484Z" fill="url(#cg)" stroke="#b9a581" stroke-width="3"/><path d="M45 80L16 18L310 18L284 80Z" fill="#ded2b2"/><path d="M35 18L290 18" stroke="#947e5c" stroke-width="5"/><rect x="52" y="220" width="233" height="132" fill="#214a45"/><text x="75" y="270" fill="#f4f0de" font-family="Arial" font-size="36" font-weight="700">CAFÉ</text><text x="76" y="305" fill="#d6e5d8" font-family="Arial" font-size="16">100% ARABICA</text></g></svg>`;
 return `<svg viewBox="0 0 860 650" role="img" aria-label="Упаковка защитных перчаток"><defs><linearGradient id="gg" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#cdd7da"/><stop offset="1" stop-color="#829ead"/></linearGradient></defs><g transform="translate(185 140) rotate(-8 230 200)"><path d="M10 85L447 48L490 378L52 422Z" fill="url(#gg)" stroke="#718996" stroke-width="3"/><rect x="78" y="131" width="334" height="212" fill="#f4f7f6"/><text x="106" y="201" font-family="Arial" font-size="34" font-weight="700" fill="#234f72">NITRILE</text><text x="106" y="239" font-family="Arial" font-size="16" fill="#537488">POWDER FREE</text><path d="M245 265l4-56q0-15 12-15t12 15l8 42v-78q0-15 11-14q12 1 11 14v66l7-55q2-14 12-13q11 1 9 16l-6 65l8-41q2-13 11-11q10 2 7 16l-12 69q-8 56-57 56h-41q-41-9-49-41l-12-38q-5-13 6-17q10-4 16 9l18 22" fill="#73a1c7"/></g></svg>`;
}
function header(){const active=state.data.orders.filter(o=>o.status!=='cancelled').length;return `<header class="mast"><div class="mast-inner"><a class="logo" href="#market" aria-label="Optima. Закупки"><span class="logo-glyph">O<span></span></span><strong>optima<span class="logo-dot">.</span></strong></a><span class="brand-divider"></span><div class="mast-caption">ПЛАТФОРМА<br>СОВМЕСТНОГО СПРОСА</div><nav class="nav" aria-label="Основные разделы">${routes.map(r=>`<a href="#${r}" class="${state.route===r?'active':''}" ${state.route===r?'aria-current="page"':''}>${labels[r]}${r==='orders'&&active?`<span class="nav-count">${active}</span>`:''}</a>`).join('')}</nav><div class="mast-trail"><span class="mock-indicator"><i></i> ДЕМО</span><button class="theme-control" data-act="theme" aria-label="Переключить тему">${state.theme==='light'?'◑':'◐'}</button><button class="account" data-act="profile"><span>С</span>ООО «Север»</button></div></div></header>`;}
function footer(){return `<footer class="footer"><span>ОПТИМА / ПРОТОТИП 2026</span><span>Цены и компании демонстрационные. Фактические условия подтверждаются поставщиком.</span><a href="#market">Наверх ↑</a></footer>`}
function stage(o){return `<div class="stage" data-type="${esc(o.art)}"><div class="stage-top"><span>OPTIMA / OBJECT ${esc(o.sku)}</span><span>ТЕХНИЧЕСКИЙ ОБЗОР</span></div><div class="sculpture">${sculpture(o.art)}</div><div class="stage-bottom"><span class="stage-code">${esc(o.sku)}</span><span>FIG. ${String(state.data.offers.indexOf(o)+1).padStart(2,'0')} / 06</span></div><div class="spec-stamp"><strong>${esc(o.unit)}</strong><span>ЕДИНИЦА ПОСТАВКИ</span></div></div>`;}
function currentPrice(){const o=selected(),q=quote(o,qty(o));return {o,q};}
function pool(q,o){const own=Math.min(100,(q.quantity/o.threshold)*100),others=Math.min(100,(o.groupQuantity/o.threshold)*100);return `<div class="pool"><div class="pool-top"><span>НАБОР ПАРТИИ</span><span>${q.ready?'Порог достигнут':'Идёт сбор'}</span></div><div class="pool-number"><strong>${Math.round(q.progress)}<small>%</small></strong><p>общего объёма уже собрано<br>с вашим участием</p></div><div class="pool-track" role="progressbar" aria-valuenow="${Math.round(q.progress)}" aria-valuemin="0" aria-valuemax="100" aria-label="Набор группы"><i style="width:${others}%"></i><i style="width:${Math.min(100-others,own)}%"></i></div><div class="pool-split"><span><b></b>Другие компании <strong>${number(o.groupQuantity)} ${esc(o.unit)}</strong></span><span><b></b>Вы <strong>${number(q.quantity)} ${esc(o.unit)}</strong></span></div><div class="pool-detail">${q.ready?'Объём партии достигает установленного порога':`До порога осталось ${number(q.missing)} ${esc(o.unit)}`}</div></div>`;}
function calculator(){const {o,q}=currentPrice(),order=activeOrder(o.id);return `<section class="participate" id="purchase-panel" aria-label="Расчёт участия"><div class="ticket-top"><span>02 / ВАШЕ УЧАСТИЕ</span><strong>${order?'Заявка создана':'Расчёт по условиям'}</strong></div>${pool(q,o)}<div class="quantity-block"><label for="order-qty">Сколько нужно вашей компании?</label><div class="qty-box"><button data-act="minus" aria-label="Уменьшить количество">−</button><input id="order-qty" type="number" inputmode="numeric" min="${o.minQuantity}" step="${o.step}" value="${q.quantity}" aria-label="Количество товара"><span>${esc(o.unit)}</span><button data-act="plus" aria-label="Увеличить количество">+</button></div><p>Шаг заказа: ${number(o.step)} ${esc(o.unit)} · от ${number(o.minQuantity)} ${esc(o.unit)}</p></div><div class="price-lines"><div><span>Отдельная закупка</span><strong>${rub(q.retailTotalKop)}</strong></div><div><span>Общая цена, включая доставку*</span><strong>${rub(q.groupTotalKop)}</strong></div></div><div class="price-summary"><div><span>ПОТЕНЦИАЛЬНАЯ ЭКОНОМИЯ</span><strong>${rub(q.savingKop)}</strong></div><span>−${percent(q.savingPercent)}</span></div><button class="submit-deal" data-act="join" ${order?'disabled':''}>${order?'Вы уже участвуете':'Присоединиться к закупке'} <span>${order?'✓':'↗'}</span></button><p class="ticket-caption">* При достижении порога. Заявка самостоятельная, оплата и документы отдельно.</p></section>`;}
function shelf(){const o=selected(),arr=state.data.offers.filter(x=>state.category==='Все'||x.category===state.category).filter(x=>[x.name,x.spec,x.supplier,x.sku].join(' ').toLowerCase().includes(state.search.toLowerCase()));return `<section class="offer-shelf" aria-label="Другие предложения"><div class="shelf-title"><div><span>03 / РЫНОК ПРЕДЛОЖЕНИЙ</span><h2>Товары в подборке <i>${arr.length}</i></h2></div><button data-act="new-need" class="subtle-action">Не нашли своё? Добавить потребность ↗</button></div><div class="shelf-controls"><label><span class="sr">Поиск по каталогу</span><input id="offer-search" type="search" value="${esc(state.search)}" placeholder="Товар, артикул или поставщик…"></label><label><span class="sr">Категория</span><select id="category"><option>Все</option>${['Упаковка','Офис','Расходники'].map(c=>`<option ${state.category===c?'selected':''}>${c}</option>`).join('')}</select></label></div><div class="shelf-list">${arr.length?arr.map((x,i)=>{const q=quote(x,x.defaultQuantity);return `<button class="shelf-row ${o.id===x.id?'on':''}" data-act="select" data-id="${esc(x.id)}" aria-pressed="${o.id===x.id}"><span class="shelf-n">${String(i+1).padStart(2,'0')}</span><span class="shelf-name"><b>${esc(x.name)}</b><small>${esc(x.sku)} · ${esc(x.supplier)}</small></span><span class="shelf-progress"><i><b style="width:${Math.round(q.progress)}%"></b></i><small>${Math.round(q.progress)}% собрано</small></span><span class="shelf-money">${rub(q.groupTotalKop)}</span><span class="shelf-arr">↗</span></button>`}).join(''):`<div class="none">Нет совпадений. Измените поиск или категорию.</div>`}</div></section>`;}
function market(){const o=selected(),q=quote(o,qty(o));return `<div class="page market-page"><div class="breadcrumbs"><span>ПЛАТФОРМА / КАТАЛОГ</span><span>ПРЕДЛОЖЕНИЕ ${esc(o.sku)}</span></div><div class="product-heading"><div><div class="fine-label"><span class="signal-dot"></span>${esc(o.category.toUpperCase())} <span class="slash">/</span> ${esc(o.sku)}</div><h1>${esc(o.name)}<span class="title-period">.</span></h1><p>Поставщик: <strong>${esc(o.supplier)}</strong> <i></i> Сбор заявок до ${day(o.deadline)}</p></div><div class="heading-aside"><span>01 — 06</span><p>Индивидуальная закупка<br>с силой общего объёма.</p></div></div><div class="deal-layout"><div class="visual-side">${stage(o)}<div class="spec-grid"><div><span>АРТИКУЛ</span><strong>${esc(o.sku)}</strong></div><div><span>ХАРАКТЕРИСТИКИ</span><strong>${esc(o.spec)}</strong></div><div><span>ПОСТАВКА</span><strong>${day(o.deliveryDate)}*</strong></div><div><span>УЧАСТНИКИ</span><strong>${number(o.participants)} компаний</strong></div></div></div>${calculator()}</div>${shelf()}<div class="bottom-note"><span>ОБЩИЙ ОБЪЁМ ≠ ОБЩИЙ ЗАКАЗ.</span><p>Каждая компания оформляет участие самостоятельно. Все цены и условия демонстрационные.</p></div><div class="mobile-deal-dock"><div><small>ПОТЕНЦИАЛЬНАЯ ЭКОНОМИЯ</small><strong>${rub(q.savingKop)}</strong></div><button data-act="jump-quote">К расчёту ↗</button></div></div>`;}
function secondaryIntro(index,kicker,title,sub,action=''){return `<div class="inner-intro"><span>${index} / ${kicker}</span><h1>${title}<i>.</i></h1><div><p>${sub}</p>${action}</div></div>`}
function ordersPage(){const active=state.data.orders.filter(o=>o.status!=='cancelled'),saving=active.reduce((a,o)=>a+o.quote.savingKop,0);return `<section class="page secondary-page">${secondaryIntro('02','УЧАСТИЕ','Мои заказы','Каждая заявка самостоятельная. Здесь хранятся созданные и отменённые демозаказы.',`<button data-act="go-market" class="text-cta">Открыть каталог ↗</button>`)}<div class="notice-strip"><span>АКТИВНЫХ ЗАЯВОК</span><strong>${String(active.length).padStart(2,'0')}</strong><span>ПОТЕНЦИАЛЬНАЯ ЭКОНОМИЯ</span><strong>${rub(saving)}</strong></div><div class="ledger-head"><span>НОМЕР / ТОВАР</span><span>СТАТУС</span><span>ВАША СТОИМОСТЬ</span><span></span></div><div class="ledger">${state.data.orders.length?state.data.orders.map(order=>{const o=offer(order.offerId);return `<button class="ledger-row" data-act="detail-order" data-id="${esc(order.id)}"><span><small>${esc(order.number)}</small><strong>${esc(o?.name||'Неизвестная позиция')}</strong><em>${number(order.quantity)} ${esc(o?.unit||'')} · ${esc(o?.supplier||'')}</em></span><span class="ledger-state ${order.status==='cancelled'?'cancelled':''}">${status(order)}</span><strong>${rub(order.quote.groupTotalKop)}</strong><span>↗</span></button>`}).join(''):`<div class="ledger-empty"><strong>Пока ничего не заказано.</strong><p>Выберите товар, настройте свой объём и подтвердите заявку. Она появится здесь.</p><button data-act="go-market">Посмотреть предложения ↗</button></div>`}</div></section>`}
function needsPage(){return `<section class="page secondary-page">${secondaryIntro('03','ПЛАНИРОВАНИЕ','Потребности','Сохраняйте список позиций и находите подходящие групповые закупки.',`<div class="intro-actions"><button data-act="import" class="text-cta">Импорт CSV / JSON ↗</button><button data-act="new-need" class="filled-cta">Добавить потребность +</button></div>`)}<div class="ledger-head need-head"><span>НАИМЕНОВАНИЕ</span><span>КОЛИЧЕСТВО</span><span>ПОДБОР</span><span></span></div><div class="ledger">${state.data.needs.map(n=>{const matched=matchingOffers(n,state.data.offers)[0];return `<div class="ledger-row need-row"><span><small>${esc(n.spec||'Без дополнительных характеристик')}</small><strong>${esc(n.name)}</strong><em>${n.deadline?'До '+day(n.deadline):'Срок не указан'}</em></span><strong>${number(n.quantity)} ${esc(n.unit)}</strong><span>${matched?`<button class="match-btn" data-act="match" data-id="${esc(matched.id)}" aria-label="Выбрать предложение ${esc(matched.name)}">Предложение найдено ↗</button>`:'Ищем предложение'}</span><button class="remove" data-act="delete-need" data-id="${esc(n.id)}" aria-label="Удалить ${esc(n.name)}">×</button></div>`}).join('')}</div><div class="import-help">Доступны файлы CSV и JSON · Не более 100 позиций за один импорт · Данные сохраняются локально.</div></section>`}
function analyticsPage(){const offers=state.data.offers,items=offers.map(o=>({...o,q:quote(o,o.defaultQuantity)})),sums=sumQuotes(offers),max=Math.max(...items.map(x=>x.q.savingKop));return `<section class="page secondary-page">${secondaryIntro('04','АНАЛИТИКА','Экономика закупок','Сравнение групповой и индивидуальной стоимости на примере шести предложений.',`<button class="text-cta" data-act="export">Экспорт CSV ↗</button>`)}<div class="big-statement"><span>ПОТЕНЦИАЛ ПО КАТАЛОГУ</span><strong>${rub(sums.savingKop)}</strong><p>Возможная экономия при достижении порога каждой партии. Не гарантированная сумма.</p></div><div class="analytics-columns"><div><h2>Где возникает выгода</h2><div class="bar-list">${items.map(item=>`<div class="bar-item"><div><span>${esc(item.name)}</span><b>${rub(item.q.savingKop)}</b></div><i><b style="width:${Math.round(item.q.savingKop/max*100)}%"></b></i></div>`).join('')}</div></div><aside class="method"><span>МЕТОДИКА / 01</span><h3>Считаем<br>прозрачно.</h3><p>Отдельная цена и групповая стоимость включают соответствующую доставку. Все вычисления используют целые копейки.</p><div><span>1</span> Сумма отдельной закупки</div><div><span>2</span> Цена общей партии</div><div><span>3</span> Разница — потенциальная экономия</div></aside></div></section>`}
function modal(){if(!state.modal)return '';const v=state.modal;let body='';if(v.type==='join'){const {o,q}=currentPrice();body=`<div class="modal-index">ПОДТВЕРЖДЕНИЕ УЧАСТИЯ / ${esc(o.sku)}</div><h2>Ваш заказ.<br>Ваши условия.</h2><p>Вы оформляете самостоятельную демонстрационную заявку. Реальных платежей не производится.</p><div class="modal-order"><div><span>Товар</span><strong>${esc(o.name)}</strong></div><div><span>Количество</span><strong>${number(q.quantity)} ${esc(o.unit)}</strong></div><div><span>Стоимость при общем объёме</span><strong>${rub(q.groupTotalKop)}</strong></div><div><span>Сбор до</span><strong>${day(o.deadline)}</strong></div></div><form id="join-form"><label class="checkline"><input required name="accepted" type="checkbox"> <span>Подтверждаю ознакомление с демонстрационными условиями закупки.</span></label><button class="modal-primary" type="submit" ${state.busy?'disabled':''}>Создать заявку ↗</button></form>`;}else if(v.type==='need'){body=`<div class="modal-index">НОВАЯ ПОТРЕБНОСТЬ</div><h2>Добавить<br>позицию.</h2><p>Система сопоставит ваши параметры с доступными групповыми предложениями.</p><form id="need-form" class="modal-fields"><label>Название товара<input required name="name" maxlength="120" placeholder="Например, картонные коробки"></label><label>Характеристики<input name="spec" maxlength="180" placeholder="Размер, материал, фасовка"></label><div class="field-pair"><label>Количество<input required name="quantity" type="number" min="1" max="10000000" placeholder="100"></label><label>Единица<select name="unit"><option>шт.</option><option>пач.</option><option>уп.</option><option>рул.</option><option>кг</option></select></label></div><label>Нужно до<input type="date" name="deadline" min="2026-10-17"></label><button class="modal-primary" type="submit">Сохранить потребность ↗</button></form>`;}else if(v.type==='order'){const od=state.data.orders.find(x=>x.id===v.id),o=offer(od?.offerId);body=od?`<div class="modal-index">ЗАЯВКА ${esc(od.number)}</div><h2>${esc(o?.name||'Ваш заказ')}.</h2><div class="modal-order"><div><span>Статус</span><strong>${status(od)}</strong></div><div><span>Количество</span><strong>${number(od.quantity)} ${esc(o?.unit||'')}</strong></div><div><span>Стоимость</span><strong>${rub(od.quote.groupTotalKop)}</strong></div><div><span>Потенциальная экономия</span><strong>${rub(od.quote.savingKop)}</strong></div></div>${od.status!=='cancelled'?`<button data-act="cancel-order" data-id="${esc(od.id)}" class="modal-danger">Отменить заявку</button>`:''}<p>Заказ демонстрационный, платёж не выполняется.</p>`:'';}else if(v.type==='profile'){body='<div class="modal-index">РАБОЧИЙ ПРОФИЛЬ</div><h2>ООО «Север».</h2><p>Демо-профиль покупателя. Серверная авторизация и реквизиты будут подключены после интеграции.</p>';}return `<div class="modal-backdrop" data-act="close" role="presentation"><div class="modal" role="dialog" aria-modal="true"><button class="modal-x" data-act="close" aria-label="Закрыть">×</button>${body}</div></div>`;}
function toast(){return state.message?`<div role="status" class="toast ${state.message.error?'error':''}">${esc(state.message.text)}<button data-act="dismiss">×</button></div>`:'';}
function render(){if(!state.data)return;const page={market,orders:ordersPage,needs:needsPage,analytics:analyticsPage}[state.route]||market;document.documentElement.dataset.theme=state.theme;$('#app').innerHTML=header()+`<main id="main">${page()}</main>`+footer()+modal()+toast();document.title=`Optima / ${labels[state.route]}`;}
function alertMsg(text,error=false){state.message={text,error};render();}
async function update(){state.data=await api.bootstrap();if(!offer(state.selected))state.selected=state.data.offers[0]?.id;render()}
async function doTask(task,success){if(state.busy)return;state.busy=true;try{await task();state.modal=null;state.message={text:success,error:false};await update()}catch(e){state.message={text:e.message||'Ошибка',error:true};render()}finally{state.busy=false}}
function navigate(route){if(!routes.includes(route))return;state.route=route;state.modal=null;location.hash=route;render();window.scrollTo({top:0,behavior:'instant'});}
function download(filename,content){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type:'text/csv;charset=utf-8'}));a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),500)}
$('#app').addEventListener('click',async e=>{const b=e.target.closest('[data-act]');if(!b)return;const a=b.dataset.act,id=b.dataset.id;
if(a==='select'){state.selected=id;persist();render();window.scrollTo({top:0,behavior:'smooth'});return;}
if(a==='theme'){state.theme=state.theme==='light'?'dark':'light';persist();render();return;}
if(a==='profile'){state.modal={type:'profile'};render();return;}
if(a==='dismiss'){state.message=null;render();return;}
if(a==='minus'||a==='plus'){const o=selected(),v=qty(o)+(a==='plus'?o.step:-o.step);state.qty[o.id]=roundStep(Math.max(o.minQuantity,v),o.step,o.minQuantity);persist();render();return;}
if(a==='jump-quote'){$('#purchase-panel')?.scrollIntoView({behavior:'smooth',block:'start'});return;}
if(a==='join'){state.modal={type:'join'};render();return;}
if(a==='close'){if(e.target===b||b.classList.contains('modal-x')){state.modal=null;render()}return;}
if(a==='new-need'){state.modal={type:'need'};render();return;}
if(a==='import'){$('#upload').click();return;}
if(a==='export'){download('optima-analytics.csv',csvExport(state.data.offers.map(o=>{const q=quote(o,o.defaultQuantity);return {number:o.sku,name:o.name,quantity:q.quantity,unit:o.unit,status:'Пример',groupTotalRUB:q.groupTotalKop/100,savingRUB:q.savingKop/100}})));return;}
if(a==='go-market'){navigate('market');return;}
if(a==='detail-order'){state.modal={type:'order',id};render();return;}
if(a==='cancel-order'){await doTask(()=>api.cancelOrder(id),'Заявка отменена');return;}
if(a==='delete-need'){await doTask(()=>api.deleteNeed(id),'Потребность удалена');return;}
if(a==='match'){state.selected=id;persist();navigate('market');return;}
});
$('#app').addEventListener('change',e=>{if(e.target.id==='category'){state.category=e.target.value;render();return;}if(e.target.id==='order-qty'){const o=selected(),v=Number(e.target.value);state.qty[o.id]=roundStep(Number.isFinite(v)&&v>0?v:o.defaultQuantity,o.step,o.minQuantity);persist();render();return;}});
function previewTypedQuantity(raw){const o=selected(),value=Number(raw);if(!Number.isFinite(value)||value<=0)return;const q=quote(o,value),panel=$('#purchase-panel');if(!panel)return;
 const p1=panel.querySelectorAll('.price-lines strong');if(p1.length===2){p1[0].textContent=rub(q.retailTotalKop);p1[1].textContent=rub(q.groupTotalKop)}
 const total=panel.querySelector('.price-summary strong');if(total)total.textContent=rub(q.savingKop);
 const pct=panel.querySelector('.price-summary>span');if(pct)pct.textContent='−'+percent(q.savingPercent);
 const poolNum=panel.querySelector('.pool-number>strong');if(poolNum)poolNum.innerHTML=Math.round(q.progress)+'<small>%</small>';
 const fillers=panel.querySelectorAll('.pool-track i');if(fillers.length===2){const others=Math.min(100,o.groupQuantity/o.threshold*100);fillers[0].style.width=others+'%';fillers[1].style.width=Math.min(100-others,q.quantity/o.threshold*100)+'%'}
 const group=panel.querySelector('.pool-detail');if(group)group.textContent=q.ready?'Объём партии достигает установленного порога':`До порога осталось ${number(q.missing)} ${o.unit}`;
 const stateLabel=panel.querySelector('.pool-top span:last-child');if(stateLabel)stateLabel.textContent=q.ready?'Порог достигнут':'Идёт сбор';
 const own=panel.querySelector('.pool-split>span:nth-child(2) strong');if(own)own.textContent=number(q.quantity)+' '+o.unit;
 const progress=panel.querySelector('.pool-track');if(progress)progress.setAttribute('aria-valuenow',String(Math.round(q.progress)));
}
$('#app').addEventListener('input',e=>{if(e.target.id==='order-qty'){previewTypedQuantity(e.target.value);return;}if(e.target.id==='offer-search'){const start=e.target.selectionStart,end=e.target.selectionEnd;state.search=e.target.value;render();const next=$('#offer-search');next?.focus({preventScroll:true});try{next.setSelectionRange(start,end)}catch{};}});
$('#app').addEventListener('submit',async e=>{e.preventDefault();if(e.target.id==='join-form'){const o=selected();await doTask(()=>api.createOrder({offerId:o.id,quantity:qty(o),termsVersion:o.termsVersion,accepted:!!e.target.elements.accepted.checked}),'Заявка создана в разделе «Мои заказы»');return;}if(e.target.id==='need-form'){await doTask(()=>api.createNeed(Object.fromEntries(new FormData(e.target))),'Потребность сохранена');}});
$('#upload').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;try{if(file.size>2e6)throw new Error('Максимальный размер файла 2 МБ');const n=parseNeeds(await file.text(),file.name);await doTask(()=>api.importNeeds(n),`Импортировано: ${n.length} позиций`)}catch(e){alertMsg(e.message,true)}finally{e.target.value=''}});
window.addEventListener('hashchange',()=>{const r=location.hash.slice(1);if(routes.includes(r)&&r!==state.route){state.route=r;state.modal=null;render();window.scrollTo(0,0)}});
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.modal){state.modal=null;render()}if(e.key==='/'&&state.route==='market'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)){e.preventDefault();$('#offer-search')?.focus()}});
(async()=>{try{await update()}catch(e){$('#app').innerHTML='<div class="fatal"><h1>Не удалось открыть Optima</h1><p>'+esc(e.message)+'</p><button onclick="location.reload()">Повторить</button></div>'}})();